const ResonaLogo = () => {
  const animation = useRef(new Animated.Value(0)).current;

  // Calculate exact path length
  const properties = new svgPathProperties(pathData);
  const pathLength = properties.getTotalLength();

  useEffect(() => {
    Animated.timing(animation, {
      toValue: 1,
      duration: 3000, // how long the writing takes
      useNativeDriver: true,
    }).start();
  }, []);

  const strokeDashoffset = animation.interpolate({
    inputRange: [0, 1],
    outputRange: [pathLength, 0],
  });

  return (
    <Svg height="200" width="400" viewBox="0 0 600 200">
      <Path
        d={pathData}
        stroke="white"
        strokeWidth={3}
        fill="none"
        strokeDasharray={pathLength}
        strokeDashoffset={strokeDashoffset}
      />
    </Svg>
  );
};

export default ResonaLogo;
